local files,fail={},false;local fs={getInfo=function(p)return files[p]and{}or nil end,read=function(p)return files[p] end,write=function(p,v)if fail then return false,"injected" end;files[p]=v;return true end,remove=function(p)files[p]=nil;return true end,createDirectory=function()return true end}
