local function newRun(avatar,source)
  serial=serial+1;if source then source=Serializer.decode(Serializer.encode(source)) else source={version="red",player={id=serial},party={},boxes={{}},inventory={},pcItems={},money=0,hallOfFame={{}},modData={}} end
  assert(archive.beginJourney(source,{runRules=archive.safeRunRulesSnapshot(source)}));local save={version="red",player={id=source.player.id},party={},boxes={{}},inventory={},pcItems={},money=0,hallOfFame={{}},modData={}}
