local function same(a,b,seen) if type(a)~=type(b) then return false end;if type(a)~="table" then return a==b end;seen=seen or {};if seen[a]==b then return true end;seen[a]=b;for k,v in pairs(a) do if not same(v,b[k],seen) then return false end end;for k in pairs(b) do if a[k]==nil then return false end end;return true end
