function mega.grantStone(stone,g)local b=g.save.modData.kanto_ascendant;b.mega_evolution=type(b.mega_evolution)=="table"and b.mega_evolution or{stones={}};b.mega_evolution.stones=type(b.mega_evolution.stones)=="table"and b.mega_evolution.stones or{};if b.mega_evolution.stones[stone]then return false end;b.mega_evolution.stones[stone]=true;return true end
